WITH fixes(pos,why) AS (VALUES (4,'Correto. O art. 14, § 1º, I, da Constituição torna obrigatório o voto e o alistamento para maiores de 18 anos, ressalvados os grupos para os quais são facultativos.'),(9,'Correto. A filiação partidária é condição de elegibilidade no art. 14, § 3º, V, da Constituição; não basta apenas ter idade mínima.'),(10,'Correto. O domicílio eleitoral na circunscrição consta do art. 14, § 3º, IV, da Constituição como condição para concorrer ao cargo.'),(14,'Correto. O art. 14, § 4º, da Constituição considera os analfabetos inelegíveis. Atenção: isso não significa que estejam proibidos de votar.'),(16,'Correto. O art. 14, § 5º, da Constituição admite uma única reeleição para período subsequente ao mandato do Presidente da República.'),(17,'Correto. O art. 14, § 6º, da Constituição exige renúncia até seis meses antes do pleito para o chefe do Executivo disputar outro cargo.'),(19,'Correto. O art. 15, III, da Constituição prevê suspensão dos direitos políticos em caso de condenação criminal transitada em julgado, enquanto durarem seus efeitos.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL AND length(trim(coalesce(e.value->>'why','')))<25 THEN jsonb_set(e.value,'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.pos=e.ordinality WHERE sm.slug='constitucional-direitos-politicos-elegibilidade' GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;